UPDATE /*LGVPAY00026.updateEmailEmpSendError*/
       tb_pay_slip_send_n 
SET    payroll_calculation_exec_id     = #{payrollCalculationExecId}             
     , transfer_flag                       = #{sendFlag}
     , mail_send_error_content                      = #{createError}
     , last_update_user_id             = #{USER_SESSION.applicationUserId}            		/* 최종수정사용자아이디 */
     , last_update_date                = sysdate                 							/* 최종수정일자 */
WHERE  employee_no                     = #{employeeNo}
 AND   payment_yyyymm                       = #{payMonth}

UPDATE /*LGVPAY00026.updateEmailEmpSendError*/
       tb_pay_slip_send_n 
SET    payroll_calculation_exec_id     = #{payrollCalculationExecId}             
     , slip_creation_flag             = #{createPayslipFlag}
     , error_message_content            = #{createpayslipError}
     , last_update_user_id             = #{USER_SESSION.applicationUserId}            		/* 최종수정사용자아이디 */
     , last_update_date                = sysdate                 							/* 최종수정일자 */
WHERE  employee_no                     = #{employeeNo}
 AND   payment_yyyymm                       = #{payMonth}
